(function () {
    'use strict';

    const settings = window.BOOK_301_AUDIO;
    const script = document.currentScript;
    const lesson = Number(script.dataset.lesson);
    const config = settings[String(lesson)];
    if (!config || document.getElementById('book301Audio')) return;

    const panel = document.createElement('section');
    panel.className = 'card book301-player';
    panel.setAttribute('aria-label', 'MP3 giáo trình bài ' + lesson);
    panel.innerHTML = '<h2 class="card-title">MP3 GIÁO TRÌNH · BÀI ' + lesson + '</h2>' +
        '<audio id="book301Audio" controls preload="metadata" aria-label="Ghi âm bài ' + lesson + '"></audio>' +
        '<div class="book301-buttons"></div>' +
        '<p id="book301AudioStatus" role="status" aria-live="polite">Chọn mục để nghe bản ghi âm của bài.</p>';

    const content = document.querySelector('.content-area');
    if (!content) return;
    content.prepend(panel);
    const audio = panel.querySelector('audio');
    audio.src = new URL(config.src, document.baseURI).href;
    const status = panel.querySelector('#book301AudioStatus');
    let active = null;
    let pendingSeek = null;

    const style = document.createElement('style');
    style.textContent = '.book301-player audio{display:block;width:100%;margin:12px 0}' +
        '.book301-buttons{display:flex;gap:8px;flex-wrap:wrap}' +
        '.book301-buttons button,.book301-section-button{font:14px Arial,sans-serif;min-height:42px;' +
        'padding:9px 13px;border:1px solid #ccc;border-radius:5px;background:#fff;color:#1A1A2E;cursor:pointer}' +
        '.book301-buttons button[aria-pressed="true"]{background:#C0392B;color:#fff;border-color:#C0392B}' +
        '.book301-section-button{margin:0 0 14px;border-color:#C0392B;color:#C0392B}' +
        '#book301AudioStatus{font:13px/1.6 Arial,sans-serif;color:#555;margin-top:10px}' +
        '@media print{.book301-player,.book301-section-button{display:none!important}}';
    document.head.appendChild(style);

    function time(seconds) {
        const value = Math.max(0, Math.floor(seconds || 0));
        return String(Math.floor(value / 60)).padStart(2, '0') + ':' + String(value % 60).padStart(2, '0');
    }

    function update() {
        const range = active || { start: 0, end: config.duration, label: 'Toàn bài' };
        const current = Math.max(0, audio.currentTime - range.start);
        const total = Math.max(0, range.end - range.start);
        const playing = !audio.paused && !audio.ended;
        panel.querySelectorAll('button[data-range]').forEach(function (button) {
            button.setAttribute('aria-pressed', String(playing && button.dataset.range === range.key));
        });
        status.textContent = (playing ? 'Đang nghe ' : 'MP3 · ') + range.label + ' · ' + time(current) + ' / ' + time(total);

        if (range.key !== 'retell') return;
        const progress = document.getElementById('progressBar1') || document.getElementById('listenProgress');
        const display = document.getElementById('timeDisplay1') || document.getElementById('listenTime');
        const button = document.getElementById('playBtn1') || document.getElementById('listenPlayBtn');
        if (progress) progress.style.width = Math.min(100, total ? current / total * 100 : 0) + '%';
        if (display) display.textContent = time(current) + ' / ' + time(total);
        if (button) button.textContent = playing ? '❚❚' : '▶';
    }

    function seek(seconds) {
        if (audio.readyState < 1) {
            pendingSeek = seconds;
            audio.load();
            return;
        }
        audio.currentTime = Math.min(seconds, audio.duration || config.duration);
    }

    function play(range) {
        if (active && active.key === range.key && !audio.paused) {
            audio.pause();
            return;
        }
        const resume = active && active.key === range.key && audio.currentTime >= range.start && audio.currentTime < range.end - 0.08;
        active = range;
        if ('speechSynthesis' in window) window.speechSynthesis.cancel();
        if (!resume) seek(range.start);
        audio.play().catch(function () {
            status.textContent = 'Chưa phát được MP3. Nhấn nút phát trên thanh âm thanh để thử lại.';
        });
    }

    function part(index) {
        const selected = config.parts[index];
        if (selected) play(Object.assign({ key: 'part-' + index }, selected));
    }

    function addButton(label, key, action) {
        const button = document.createElement('button');
        button.type = 'button';
        button.textContent = label;
        button.dataset.range = key;
        button.setAttribute('aria-pressed', 'false');
        button.addEventListener('click', action);
        panel.querySelector('.book301-buttons').appendChild(button);
    }

    addButton('▶ Toàn bài', 'all', function () {
        play({ key: 'all', label: 'Toàn bài', start: 0, end: config.duration });
    });
    config.parts.forEach(function (item, index) {
        addButton('▶ ' + item.label, 'part-' + index, function () { part(index); });
    });
    if (config.retell) {
        addButton('▶ Nghe thuật lại', 'retell', function () {
            play(Object.assign({ key: 'retell', label: 'Nghe thuật lại' }, config.retell));
        });
    }

    const sections = [
        { id: 'maucau', part: 0 },
        { id: 'damthoai', part: 1 },
        { id: 'tuvung', part: 2 },
        { id: 'baitap', part: config.parts.length - 1 }
    ];
    if (lesson <= 3) sections.push({ id: 'nguam', part: 3 });
    sections.forEach(function (entry) {
        const section = document.getElementById(entry.id);
        if (!section) return;
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'book301-section-button';
        button.textContent = '▶ MP3 · ' + config.parts[entry.part].label;
        button.addEventListener('click', function () { part(entry.part); });
        section.prepend(button);

        if (!['maucau', 'tuvung'].includes(entry.id)) return;
        const heading = section.querySelector('.card-title');
        if (!heading) return;
        heading.dataset.book301 = 'true';
        heading.onclick = function () { part(entry.part); };
        const existingButton = heading.querySelector('.header-audio');
        if (existingButton) {
            existingButton.title = 'Nghe MP3 ' + config.parts[entry.part].label;
            existingButton.onclick = function (event) {
                event.stopPropagation();
                part(entry.part);
            };
        }
    });

    document.addEventListener('click', function (event) {
        const target = event.target.closest('[onclick]');
        if (target && target.closest('[data-book301="true"]')) return;
        const handler = target && target.getAttribute('onclick');
        if (handler && /speakText|playPhonetic|playPinyin|playTone|playMP3|playDialogue/.test(handler)) audio.pause();
    }, true);

    if (config.retell) {
        const initialDisplay = document.getElementById('timeDisplay1') || document.getElementById('listenTime');
        if (initialDisplay) initialDisplay.textContent = '00:00 / ' + time(config.retell.end - config.retell.start);
        window.playListeningAudio = function () {
            play(Object.assign({ key: 'retell', label: 'Nghe thuật lại' }, config.retell));
        };
        const seekRetell = function (event) {
            const bounds = event.currentTarget.getBoundingClientRect();
            const ratio = Math.max(0, Math.min(1, (event.clientX - bounds.left) / bounds.width));
            active = Object.assign({ key: 'retell', label: 'Nghe thuật lại' }, config.retell);
            seek(active.start + ratio * (active.end - active.start));
            update();
        };
        window.seekAudio = seekRetell;
        window.seekListening = seekRetell;
    }

    audio.addEventListener('loadedmetadata', function () {
        if (pendingSeek !== null) {
            const value = pendingSeek;
            pendingSeek = null;
            seek(value);
        }
        update();
    });
    audio.addEventListener('timeupdate', function () {
        if (active && audio.currentTime >= active.end) audio.pause();
        update();
    });
    audio.addEventListener('play', update);
    audio.addEventListener('pause', update);
    audio.addEventListener('ended', update);
    audio.addEventListener('error', function () {
        status.textContent = 'Không tải được MP3 bài ' + lesson + '. Hãy kiểm tra kết nối và thử lại.';
    });
    window.addEventListener('pagehide', function () { audio.pause(); });
    window.book301Audio = { audio: audio, playPart: part };
}());
